final case class LegacyOrder(orderId: String, sku: String, qty: Int)

object LegacyOrder {
  implicit val decoder: Decoder[LegacyOrder] = Decoder.instance { c =>
    for {
      id  <- c.downField("order_id").as[String]
      sku <- c.downField("sku").as[String]
      qty <- c.downField("qty").as[Int]
    } yield LegacyOrder(id, sku, qty)
  }
  implicit val encoder: Encoder[LegacyOrder] = Encoder.instance(o =>
    Json.obj("order_id" -> o.orderId.asJson, "sku" -> o.sku.asJson, "qty" -> o.qty.asJson))
}
